import{_ as t}from"./chunks/files.B17OUyrr.js";import{_ as i,c as e,o as r,a2 as o}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"认识 qDiff","description":"用 qDiff 比较文件、文件夹与项目改动的简明介绍。","frontmatter":{"title":"认识 qDiff","description":"用 qDiff 比较文件、文件夹与项目改动的简明介绍。"},"headers":[],"relativePath":"zh-CN/guide/introduction.md","filePath":"zh-CN/guide/introduction.md","lastUpdated":1793948370000}'),l={name:"zh-CN/guide/introduction.md"};function s(n,a,d,f,h,c){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="认识-qdiff" tabindex="-1">认识 qDiff <a class="header-anchor" href="#认识-qdiff" aria-label="Permalink to &quot;认识 qDiff&quot;">​</a></h1><p>qDiff 只回答一个问题：<strong>到底改了哪儿？</strong> 把两个版本并排放好，不同的地方 会用颜色标出来，不用再靠眼睛一行一行对。</p><img src="'+t+'" alt="两份文件并排比较" class="guide-shot"><h2 id="大家最常拿来做的三件事" tabindex="-1">大家最常拿来做的三件事 <a class="header-anchor" href="#大家最常拿来做的三件事" aria-label="Permalink to &quot;大家最常拿来做的三件事&quot;">​</a></h2><ul><li><strong>比两份文件</strong> —— 初稿与改后稿、改前改后的配置、两次导出的内容。一行里 改动的那几个字也会单独标出来。</li><li><strong>比两个文件夹</strong> —— 工作目录和它的备份。多了什么、改了什么、少了什么， 一眼就能挑出来，还能顺手让两边一致。</li><li><strong>看一个项目文件夹</strong> —— 改动过的文件排成一列，逐个看差异、提交，不用 在几个窗口之间来回切。</li></ul><p>图片、压缩包，以及不是纯文本的文件也能比，<a href="./more.html">看看还有哪些用法</a>。</p><h2 id="三步开始" tabindex="-1">三步开始 <a class="header-anchor" href="#三步开始" aria-label="Permalink to &quot;三步开始&quot;">​</a></h2><ol><li>打开 qDiff，把两个文件或文件夹拖到窗口里；也可以从「文件」菜单选择。</li><li>看带颜色的行。点侧边的小地图，或者用「上一处 / 下一处」按钮逐个查看。</li><li>需要调整就直接改、复制、同步；要给别人看，就把这次比较存成一张图。</li></ol><div class="tip custom-block"><p class="custom-block-title">不用先设置</p><p>不用注册账号，第一次比较之前也没有什么要配置的，离线就能用。</p></div><h2 id="免费-也安心" tabindex="-1">免费，也安心 <a class="header-anchor" href="#免费-也安心" aria-label="Permalink to &quot;免费，也安心&quot;">​</a></h2><p>所有比较功能都免费。免费版只在标签条上多一个小标记，一次性购买即可去掉。 qDiff 只读取你选择的文件，不会把内容发出去，详见<a href="./../privacy/">隐私政策</a>。</p><h2 id="需要帮忙" tabindex="-1">需要帮忙？ <a class="header-anchor" href="#需要帮忙" aria-label="Permalink to &quot;需要帮忙？&quot;">​</a></h2><p><a href="./faq.html">常见问题</a>里收了最常被问到的几件事。如果还有问题， <a href="./support.html">给我们写信</a>就好。</p>',13)])])}const _=i(l,[["render",s]]);export{m as __pageData,_ as default};
